  for(const {block,note,event,low,high}of this.noteLayouts||[]){const h=Math.max(2,Math.min(8,(this.trackHeight-16)/(high-low+1)));block.style.left=event.beat*this.zoom+'px';block.style.width=Math.max(3,note.duration*this.zoom-1)+'px';block.style.top=(8+(high-note.midi)/(high-low)*(this.trackHeight-16-h))+'px';block.style.height=h+'px';}
  this.renderVisibleNotes(true);this.update(this.player.beat);this.sync();
