  const move=event=>{if(event.touches.length!==2)return;if(!this.gesture)start(event);event.preventDefault();const touches=this.gesture.ids.map(id=>[...event.touches].find(t=>t.identifier===id));if(touches.some(t=>!t))return;this.pinchPosition=midpoint(touches);if(this.gestureFrame)return;this.gestureFrame=requestAnimationFrame(()=>{this.gestureFrame=0;const g=this.gesture,p=this.pinchPosition;if(!g)return;this.applyScale(g.dx>=24?g.zoom*p.dx/g.dx:g.zoom,g.dy>=24?g.height*p.dy/g.dy:g.height);const r=this.scroll.getBoundingClientRect();this.scroll.scrollLeft=Math.max(0,g.beat*this.zoom-(p.x-r.left));if(g.row>=0){const y=this.body.getBoundingClientRect().top+36+g.row*this.trackHeight;this.scrollOwner.scrollTop+=y-p.y;} });};
